import org.apache.http.impl.client.HttpClientBuilder
import org.apache.http.impl.conn.PoolingHttpClientConnectionManager

class BadTotal {
    fun build(poolMgr: PoolingHttpClientConnectionManager) {
        HttpClientBuilder.create()
            .setConnectionManager(poolMgr)
            .setMaxConnTotal(200) // bad
            .build()
    }
}

import org.apache.http.impl.client.HttpClientBuilder
import org.apache.http.impl.conn.PoolingHttpClientConnectionManager

class BadPerRoute {
    fun build(poolMgr: PoolingHttpClientConnectionManager) {
        val builder = HttpClientBuilder.create()
        builder.setConnectionManager(poolMgr)
        builder.setMaxConnPerRoute(10) // bad
    }
}

import org.apache.http.impl.client.HttpClientBuilder

class GoodPoolSizes {
    fun build() {
        HttpClientBuilder.create()
            .setMaxConnTotal(200)
            .setMaxConnPerRoute(20)
            .build()
    }
}

import org.apache.http.impl.client.HttpClientBuilder
import org.apache.http.impl.conn.PoolingHttpClientConnectionManager

class GoodConnectionManager {
    fun build(poolMgr: PoolingHttpClientConnectionManager) {
        HttpClientBuilder.create()
            .setConnectionManager(poolMgr)
            .build()
    }
}
